    out = [row[:] for row in grid]
    bg = grid[0][0]
    by_color = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg:
                by_color.setdefault(value, []).append((r, c))
    # Join diagonal same-color markers by the segment between them. A lone
    # marker may indicate a full diagonal; preserve source markers otherwise.
    for value, points in by_color.items():
        if len(points) == 2:
            (r1, c1), (r2, c2) = points
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                r, c = r1, c1
                while True:
                    out[r][c] = value
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc
    # A singleton 6 is extended on its diagonal perpendicular to a 1 segment.
    ones = by_color.get(1, [])
    sixes = by_color.get(6, [])
    if len(ones) == 2 and len(sixes) == 1:
        (r1,c1),(r2,c2)=ones
        if abs(r2-r1)==abs(c2-c1):
            slope = 1 if (r2-r1)*(c2-c1)>0 else -1
            r,c=sixes[0]
            dc=slope
            while 0<=r<len(out) and 0<=c<len(out[0]):
                out[r][c]=6; r+=1; c+=dc
            r,c=sixes[0][0]-1,sixes[0][1]-dc
            while 0<=r<len(out) and 0<=c<len(out[0]):
                out[r][c]=6; r-=1; c-=dc
    return out
